const $ = (id) => document.getElementById(id);
const TOKEN_KEY = 'studyLockSocialToken';
const API_BASE = '';
let token = localStorage.getItem(TOKEN_KEY) || '';
let currentUser = null;
let selectedConversation = null;
let toastTimer;
let quickLinksDraft = [];
let activeQuiz = null;
let quizTimerInterval = null;
let quizAutosaveTimer = null;
let quizAutosaveBusy = false;
const DEFAULT_QUICK_LINKS = [
  { label: 'Google', url: 'https://www.google.com', icon: '🔎' },
  { label: 'YouTube', url: 'https://www.youtube.com', icon: '▶️' },
  { label: 'Gmail', url: 'https://mail.google.com', icon: '✉️' },
  { label: 'Drive', url: 'https://drive.google.com', icon: '📁' },
  { label: 'Classroom', url: 'https://classroom.google.com', icon: '🎓' },
  { label: 'ChatGPT', url: 'https://chatgpt.com', icon: '✳️' },
  { label: 'GitHub', url: 'https://github.com', icon: '🐙' },
  { label: 'LeetCode', url: 'https://leetcode.com', icon: '💻' },
  { label: 'GeeksforGeeks', url: 'https://www.geeksforgeeks.org', icon: '📗' },
  { label: 'Khan Academy', url: 'https://www.khanacademy.org', icon: '📚' }
];
const escapeHtml = (value) => String(value ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmtTime = seconds => { seconds = Math.max(0, Math.floor(Number(seconds) || 0)); const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60); return h ? `${h}h ${m}m` : `${m}m`; };
const dateFmt = value => value ? new Date(value).toLocaleString([], {month:'short', day:'numeric', hour:'2-digit', minute:'2-digit'}) : '';
function toast(message) { const el=$('toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>el.classList.remove('show'),3300); }
function message(id, text, good=false) { const el=$(id); if(!el)return; el.textContent=text||''; el.classList.toggle('good', Boolean(good)); }
async function api(path, options={}) {
  const headers = new Headers(options.headers || {}); headers.set('Accept','application/json');
  if(options.body && !(options.body instanceof FormData)) headers.set('Content-Type','application/json');
  if(token) headers.set('Authorization', `Bearer ${token}`);
  let response;
  try { response = await fetch(`${API_BASE}${path}`, {...options, headers, body: options.body && typeof options.body!=='string' && !(options.body instanceof FormData) ? JSON.stringify(options.body) : options.body}); }
  catch { throw new Error('Cannot connect to Study Lock. Check your connection and try again.'); }
  const data = await response.json().catch(()=>({}));
  if(!response.ok) { if(response.status===401 && token) { token='';localStorage.removeItem(TOKEN_KEY);showAuth(); } throw new Error(data.error || `Request failed (${response.status}).`); }
  return data;
}
function showAuth(){ $('authPanel').hidden=false; $('appPanel').hidden=true; $('signOutButton').hidden=true; currentUser=null; $('loginForm').hidden=false; $('registerForm').hidden=true; $('resetPasswordForm').hidden=true; setAuthTab('login'); }
function showApp(){ $('authPanel').hidden=true; $('appPanel').hidden=false; $('signOutButton').hidden=false; $('adminNavButton').hidden=!Boolean(currentUser?.isAdmin); $('quizAdminPanel').hidden=!Boolean(currentUser?.isAdmin); $('adminChallengePanel').hidden=!Boolean(currentUser?.isAdmin); renderQuickLinks(); }
function setAuthTab(tab){ document.querySelectorAll('[data-auth-tab]').forEach(b=>b.classList.toggle('active',b.dataset.authTab===tab)); $('loginForm').hidden=tab!=='login'; $('registerForm').hidden=tab!=='register'; }
function showView(view){ document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view)); document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!==`view-${view}`); if(view==='leaderboard')loadLeaderboard(); if(view==='quizzes')loadQuizzes(); if(view==='discover')loadDiscover(); if(view==='friends')loadFriends(); if(view==='messages')loadConversations(); if(view==='challenges')loadChallenges(); if(view==='profile')loadProfile(); if(view==='admin'&&currentUser?.isAdmin)loadAdminReports().catch(e=>toast(e.message)); }
function avatar(user){ const name=escapeHtml(user.displayName||user.username||'?'); const img=user.avatarUrl ? `<img src="${escapeHtml(user.avatarUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''; return `<span class="avatar" aria-hidden="true">${img || name.slice(0,1).toUpperCase()}</span>`; }
function personCard(user, controls='') { return `<article class="person-card"><div class="person-card-top">${avatar(user)}<div class="person-main"><b>${escapeHtml(user.displayName)}</b><small>@${escapeHtml(user.username)}</small></div></div><p>${escapeHtml(user.bio||'Still writing their learning story.')}</p><p>${(user.interests||[]).slice(0,4).map(x=>`#${escapeHtml(x)}`).join(' ')}</p><div class="person-actions">${controls}</div></article>`; }
function userButtons(user, isFriend=false, requestState='') { const view = `<button class="btn secondary small" data-view-profile="${escapeHtml(user.username)}">View profile</button>`; if(isFriend) return `${view}<button class="btn secondary small" data-message-user="${escapeHtml(user.id)}" data-username="${escapeHtml(user.username)}">Message</button><button class="btn danger small" data-block-user="${escapeHtml(user.id)}">Block</button>`; if(requestState==='pending')return `${view}<button class="btn secondary small" disabled>Request sent</button>`; return `${view}<button class="btn primary small" data-add-friend="${escapeHtml(user.username)}">Add friend</button><button class="btn secondary small" data-report-user="${escapeHtml(user.id)}">Report</button>`; }
function pointsLabel(row){return `${Number(row.points||0).toLocaleString()} pts`;}
function rankRow(row, isMine=false){const u=row.user||{};return `<div class="rank-row ${isMine?'self':''}"><span class="rank-num">${row.rank||'—'}</span>${avatar(u)}<div class="person-main"><b>${escapeHtml(u.displayName||u.username)}</b><small>@${escapeHtml(u.username)} · ${fmtTime(row.qualifyingSeconds)} · ${row.completedLessons||0} lessons</small></div><b class="rank-points">${pointsLabel(row)}</b><button class="btn secondary small" data-view-profile="${escapeHtml(u.username)}">Profile</button>${isMine?'<span class="achievement">YOU</span>':''}</div>`;}
async function afterAuth(data){token=data.token;localStorage.setItem(TOKEN_KEY,token);currentUser=data.user;showApp();await loadOverview();toast(`Welcome, ${currentUser.displayName}!`);}
async function loadMe(){const data=await api('/api/me');currentUser=data.user;showApp();$('welcomeName').textContent=currentUser.displayName;await loadOverview();}
async function loadOverview(){if(!currentUser)return; $('welcomeName').textContent=currentUser.displayName;const [stats,board,friends,challenges]=await Promise.allSettled([api('/api/me/stats?days=30'),api('/api/leaderboard?period=weekly'),api('/api/friends'),api('/api/challenges')]);
  if(stats.status==='fulfilled'){const s=stats.value.stats;$('statHours').textContent=fmtTime(s.qualifyingSeconds);$('statLessons').textContent=String(s.completedEvents);$('statVideos').textContent=String(s.uniqueVideos);const badges=s.achievements?.achievements||[];$('achievementList').innerHTML=badges.length?badges.map(b=>`<span class="achievement">${escapeHtml(b.replaceAll('-',' '))}</span>`).join(''):'<span class="muted">Complete study sessions to earn badges.</span>';}
  if(board.status==='fulfilled'){$('topLeaders').innerHTML=board.value.leaderboard.slice(0,5).map(r=>rankRow(r,String(r.user.id)===String(currentUser.id))).join('')||'<div class="empty-state">No leaderboard activity yet. Connect Study Lock and complete a lesson.</div>';const me=board.value.leaderboard.find(r=>String(r.user.id)===String(currentUser.id));$('myRank').textContent=board.value.myRank?`#${board.value.myRank}`:'—';$('myPoints').textContent=me?me.points.toLocaleString():'0';}
  if(friends.status==='fulfilled')$('myFriends').textContent=String(friends.value.friends.length);
  if(challenges.status==='fulfilled')$('dashboardChallenges').innerHTML=challenges.value.challenges.slice(0,4).map(challengeCard).join('')||'<div class="empty-state">No current challenges yet.</div>';
}
async function loadLeaderboard(){try{const period=$('leaderboardPeriod').value;const data=await api(`/api/leaderboard?period=${encodeURIComponent(period)}`);$('leaderboardList').innerHTML=data.leaderboard.map(r=>rankRow(r,String(r.user.id)===String(currentUser.id))).join('')||'<div class="empty-state">No one has opted into the leaderboard yet. Be the first to log study activity.</div>';$('leaderboardMeta').textContent=`Updated ${new Date(data.updatedAt).toLocaleString()}. ${data.pointsFormula}.`;if(data.myRank)$('myRank').textContent=`#${data.myRank}`;}catch(e){$('leaderboardList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadDiscover(query=''){try{const data=await api(`/api/users${query?`?q=${encodeURIComponent(query)}`:''}`);$('discoverList').innerHTML=data.users.map(u=>personCard(u,userButtons(u,u.isFriend,u.pendingRequest?'pending':''))).join('')||'<div class="empty-state">No public learners found. Try another username.</div>';}catch(e){$('discoverList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadFriends(){try{const [friendData,requests]=await Promise.all([api('/api/friends'),api('/api/friends/requests')]);$('friendsList').innerHTML=friendData.friends.map(u=>`<div class="person-row">${avatar(u)}<div class="person-main"><b>${escapeHtml(u.displayName)}</b><small>@${escapeHtml(u.username)}</small></div><button class="btn secondary small" data-message-user="${escapeHtml(u.id)}" data-username="${escapeHtml(u.username)}">Message</button><button class="btn danger small" data-remove-friend="${escapeHtml(u.id)}">Remove</button></div>`).join('')||'<div class="empty-state">No friends yet. Search in Discover to connect.</div>';
$('incomingRequests').innerHTML=requests.incoming.map(r=>`<div class="request-row">${avatar(r.from)}<div class="person-main"><b>${escapeHtml(r.from.displayName)}</b><small>@${escapeHtml(r.from.username)}</small></div><button class="btn primary small" data-accept-request="${escapeHtml(r.id)}">Accept</button><button class="btn secondary small" data-decline-request="${escapeHtml(r.id)}">Decline</button></div>`).join('')||'<div class="empty-state">No incoming requests.</div>';
$('outgoingRequests').innerHTML=requests.outgoing.map(r=>`<div class="request-row">${avatar(r.to)}<div class="person-main"><b>${escapeHtml(r.to.displayName)}</b><small>@${escapeHtml(r.to.username)} · pending</small></div></div>`).join('')||'<div class="empty-state">No sent requests.</div>';}catch(e){$('friendsList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadConversations(){try{const data=await api('/api/conversations');$('conversationList').innerHTML=data.conversations.map(c=>`<button class="conversation-row" data-open-conversation="${escapeHtml(c.user.id)}" data-username="${escapeHtml(c.user.username)}">${avatar(c.user)}<span class="person-main"><b>${escapeHtml(c.user.displayName)}</b><small>${escapeHtml(c.lastMessage.body.slice(0,70))}</small></span><small>${dateFmt(c.lastMessage.createdAt)}</small></button>`).join('')||'<div class="empty-state">Messages are available to friends only. Add a friend first.</div>';}catch(e){$('conversationList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function openConversation(userId,username){selectedConversation={userId,username};$('chatEmpty').hidden=true;$('chatRoom').hidden=false;$('chatTitle').textContent=`@${username}`;$('chatMessages').innerHTML='<div class="empty-state">Loading messages…</div>';await loadMessages();}
async function loadMessages(){if(!selectedConversation)return;try{const data=await api(`/api/conversations/${selectedConversation.userId}/messages`);$('chatMessages').innerHTML=data.messages.map(m=>{const mine=String(m.senderId)===String(currentUser.id);return `<div class="chat-bubble ${mine?'mine':''}">${escapeHtml(m.body)}<small>${dateFmt(m.createdAt)}${m.readAt?' · read':''}</small>${mine?'':`<button class="btn secondary small" data-report-message="${escapeHtml(m.id)}" type="button">Report message</button>`}</div>`;}).join('')||'<div class="empty-state">No messages yet. Say hello.</div>';$('chatMessages').scrollTop=$('chatMessages').scrollHeight;}catch(e){$('chatMessages').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
function challengeCard(c){const ratio=c.goal?Math.min(100,Math.round(Number(c.myProgress||0)/c.goal*100)):0;const units={study_minutes:'minutes',lessons:'lessons',streak:'days'};return `<article class="challenge-card"><span class="challenge-meta">${escapeHtml(units[c.type]||c.type)} challenge · ${escapeHtml(c.visibility)}</span><h4>${escapeHtml(c.title)}</h4><p>${escapeHtml(c.description||'Keep each other accountable.')}</p><p>${c.participantCount} participants · goal ${c.goal} ${escapeHtml(units[c.type]||'units')} · ends ${dateFmt(c.endsAt)}</p><div class="progress-track"><i style="width:${ratio}%"></i></div><div class="person-actions">${c.joined?`<span class="achievement">Joined · ${ratio}%</span><button class="btn secondary small" data-refresh-challenge-progress="${escapeHtml(c.id)}">Refresh progress</button>`:`<button class="btn primary small" data-join-challenge="${escapeHtml(c.id)}">Join challenge</button>`}<button class="btn secondary small" data-report-challenge="${escapeHtml(c.id)}">Report</button></div></article>`;}
async function loadChallenges(){try{const d=await api('/api/challenges');$('challengeList').innerHTML=d.challenges.map(challengeCard).join('')||'<div class="empty-state">No challenges yet. Create the first one.</div>';if(currentUser?.isAdmin){$('adminChallengePanel').hidden=false;await loadAdminChallenges();}}catch(e){$('challengeList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadProfile(){try{const d=await api('/api/me');currentUser=d.user;$('adminModerationPanel').hidden=!Boolean(d.user.isAdmin);$('adminNavButton').hidden=!Boolean(d.user.isAdmin);$('quizAdminPanel').hidden=!Boolean(d.user.isAdmin);$('adminChallengePanel').hidden=!Boolean(d.user.isAdmin);if(d.user.isAdmin){loadAdminReports().catch(()=>{});loadAdminQuizzes().catch(()=>{});loadAdminChallenges().catch(()=>{});}const form=$('profileForm');for(const key of ['displayName','phoneNumber','bio','avatarUrl'])form.elements[key].value=d.user[key]||'';form.elements.interests.value=(d.user.interests||[]).join(', ');form.elements.learningGoals.value=(d.user.learningGoals||[]).join(', ');const p=d.user.privacy||{};for(const key of ['profileVisibility','showOnLeaderboard','showStudyStats','allowFriendRequests','allowMessages'])form.elements[key].value=typeof p[key]==='undefined'?'':String(p[key]);for(const key of ['showOnLeaderboard','showStudyStats','allowFriendRequests'])form.elements[key].checked=p[key]!==false;form.elements.profileVisibility.value=p.profileVisibility||'public';form.elements.allowMessages.value=p.allowMessages||'friends';renderQuickLinks();}catch(e){message('profileMessage',e.message);}}
async function showPublicProfile(username){const dialog=$('publicProfileDialog');const content=$('publicProfileContent');content.innerHTML='<div class="empty-state">Loading profile…</div>';dialog.showModal();try{const [profile,stats]=await Promise.all([api(`/api/users/${encodeURIComponent(username)}`),api(`/api/users/${encodeURIComponent(username)}/stats`)]);const u=profile.user;const achievements=(u.achievements||[]).map(x=>`<span class="achievement">${escapeHtml(x.replaceAll('-',' '))}</span>`).join('');const learningStats=stats.statsVisible?`<div class="metric-grid"><div class="metric"><small>STUDY TIME · 30 DAYS</small><b>${fmtTime(stats.stats.qualifyingSeconds)}</b></div><div class="metric"><small>COMPLETED LESSONS</small><b>${stats.stats.completedLessons}</b></div><div class="metric"><small>ACTIVE DAYS</small><b>${stats.stats.activeDays}</b></div></div>`:'<p class="muted">This learner keeps study stats private.</p>';content.innerHTML=`<div class="profile-cover">${avatar(u)}<div><h3>${escapeHtml(u.displayName)}</h3><p>@${escapeHtml(u.username)} · ${u.friendsCount||0} friends</p></div></div><p>${escapeHtml(u.bio||'No bio yet.')}</p><p>${(u.interests||[]).map(x=>`#${escapeHtml(x)}`).join(' ')}</p><h4>Learning goals</h4><p>${(u.learningGoals||[]).map(escapeHtml).join(' · ')||'Not shared'}</p><h4>Achievements</h4><div class="badge-list">${achievements||'<span class="muted">No achievements shared yet.</span>'}</div><h4>Public study stats</h4>${learningStats}<div class="person-actions">${!profile.isSelf&&!profile.isFriend?`<button class="btn primary" data-add-friend="${escapeHtml(u.username)}">Add friend</button>`:''}${!profile.isSelf&&profile.isFriend?`<button class="btn secondary" data-message-user="${escapeHtml(u.id)}" data-username="${escapeHtml(u.username)}">Message</button>`:''}${!profile.isSelf?`<button class="btn secondary" data-report-user="${escapeHtml(u.id)}">Report</button><button class="btn danger" data-block-user="${escapeHtml(u.id)}">Block</button>`:''}</div>`;}catch(e){content.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('closeProfileDialog').addEventListener('click',()=>$('publicProfileDialog').close());
async function requestFriend(username){await api('/api/friends/requests',{method:'POST',body:{username}});toast(`Friend request sent to @${username}.`);await loadDiscover($('discoverQuery').value.trim());}
async function blockUser(id){if(!confirm('Block this user? This removes the friendship, prevents new requests, and disables messaging.'))return;await api(`/api/blocks/${id}`,{method:'POST',body:{}});toast('User blocked.');selectedConversation=null;$('chatRoom').hidden=true;$('chatEmpty').hidden=false;await Promise.all([loadFriends(),loadDiscover(),loadConversations()]);}
async function reportTarget(type,id){const reason=prompt('Why are you reporting this? Enter spam, harassment, inappropriate, impersonation, or other:','other');if(!reason)return;const normal=reason.toLowerCase().trim();if(!['spam','harassment','inappropriate','impersonation','other'].includes(normal)){toast('Please use one of the listed reasons.');return;}const details=prompt('Optional details (do not include private information):','')||'';await api('/api/reports',{method:'POST',body:{targetType:type,targetId:id,reason:normal,details}});toast('Report sent for review.');}
async function acceptRequest(id){await api(`/api/friends/requests/${id}/accept`,{method:'POST',body:{}});toast('Friend request accepted.');await loadFriends();}
async function declineRequest(id){await api(`/api/friends/requests/${id}/decline`,{method:'POST',body:{}});toast('Request declined.');await loadFriends();}
async function removeFriend(id){if(!confirm('Remove this friend?'))return;await api(`/api/friends/${id}`,{method:'DELETE'});toast('Friend removed.');await loadFriends();}
async function joinChallenge(id){await api(`/api/challenges/${id}/join`,{method:'POST',body:{}});toast('Challenge joined.');await loadChallenges();}
async function updateChallenge(id){await api(`/api/challenges/${id}/progress`,{method:'POST',body:{}});toast('Challenge progress refreshed from synced study activity.');await loadChallenges();}
function download(filename,text,mime){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function exportData(){const [me,stats,friends,requests]=await Promise.all([api('/api/me'),api('/api/me/stats?days=90'),api('/api/friends'),api('/api/friends/requests')]);download('study-lock-community-data.json',JSON.stringify({exportedAt:new Date().toISOString(),profile:me,stats,friends,requests},null,2),'application/json');}
async function deleteAccount(){if(!confirm('Permanently delete your Study Lock Social account and associated data? This cannot be undone.'))return;const password=prompt('Enter your password to confirm permanent deletion:');if(password===null)return;await api('/api/me',{method:'DELETE',body:{password}});token='';localStorage.removeItem(TOKEN_KEY);showAuth();toast('Account deleted.');}

async function loadAdminReports(){if(!currentUser?.isAdmin)return;const data=await api('/api/admin/reports?status=open');const reportMarkup=data.reports.map(r=>`<article class="person-card"><b>${escapeHtml(r.reason)} · ${escapeHtml(r.targetType)}</b><p>Target: ${escapeHtml(r.targetId)} · Reporter: @${escapeHtml(r.reporter?.username||'deleted-user')}</p><p>${escapeHtml(r.details||'No additional details.')}</p><small>${dateFmt(r.createdAt)}</small><div class="person-actions"><button class="btn secondary small" data-report-status="reviewed" data-report-id="${escapeHtml(r.id)}">Mark reviewed</button><button class="btn primary small" data-report-status="actioned" data-report-id="${escapeHtml(r.id)}" data-target-type="${escapeHtml(r.targetType)}" data-target-id="${escapeHtml(r.targetId)}">Action</button><button class="btn secondary small" data-report-status="dismissed" data-report-id="${escapeHtml(r.id)}">Dismiss</button></div></article>`).join('')||'<div class="empty-state">No open reports.</div>';if($('moderationList'))$('moderationList').innerHTML=reportMarkup;if($('moderationOverviewList'))$('moderationOverviewList').innerHTML=reportMarkup;}// Personal quick-launch websites (CRUD). Saved links are HTTPS-only on the server.
function linksForDisplay(){if(currentUser?.quickLinksConfigured)return (Array.isArray(currentUser.quickLinks)?currentUser.quickLinks:[]).slice(0,10);return DEFAULT_QUICK_LINKS;}
function faviconFor(link){try{return `https://www.google.com/s2/favicons?domain=${encodeURIComponent(new URL(link.url).hostname)}&sz=64`;}catch{return '';}}
function renderQuickLinks(){if(!$('quickLinksList'))return;const links=linksForDisplay();$('quickLinksList').innerHTML=links.map((l,i)=>`<a class="quick-link" href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer" title="Open ${escapeHtml(l.label)} in a new tab"><span class="quick-link-icon"><img src="${escapeHtml(faviconFor(l))}" alt="" loading="lazy" onerror="this.style.display='none'"><span>${escapeHtml(l.icon||'🔗')}</span></span><b>${escapeHtml(l.label)}</b></a>`).join('');}
function renderQuickLinkManager(){const list=$('quickLinkManageList');if(!list)return;list.innerHTML=quickLinksDraft.map((l,i)=>`<div class="quick-link-manage-row"><span class="quick-link-manage-icon">${escapeHtml(l.icon||'🔗')}</span><div class="person-main"><b>${escapeHtml(l.label)}</b><small>${escapeHtml(l.url)}</small></div><button class="btn secondary small" type="button" data-edit-link="${i}">Edit</button><button class="btn danger small" type="button" data-delete-link="${i}">Delete</button></div>`).join('')||'<div class="empty-state">No saved links. Add a site above or save the default set.</div>';}
function openQuickLinkManager(){quickLinksDraft=linksForDisplay().map(l=>({label:String(l.label),url:String(l.url),icon:String(l.icon||'🔗')}));$('quickLinkManager').hidden=!$('quickLinkManager').hidden;if(!$('quickLinkManager').hidden)renderQuickLinkManager();}
$('manageQuickLinks').addEventListener('click',openQuickLinkManager);
$('quickLinkForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget);const label=String(f.get('label')||'').trim();const url=String(f.get('url')||'').trim();const icon=String(f.get('icon')||'🔗').trim()||'🔗';try{const parsed=new URL(url);if(parsed.protocol!=='https:'||!parsed.hostname||parsed.username||parsed.password)throw new Error('Please use a valid HTTPS URL without embedded credentials.');if(!label)throw new Error('Enter a website name.');if(quickLinksDraft.length>=10)throw new Error('You can save up to 10 shortcuts.');if(quickLinksDraft.some(l=>new URL(l.url).toString()===parsed.toString()))throw new Error('That website is already in your shortcuts.');quickLinksDraft.push({label,url:parsed.toString(),icon});e.currentTarget.reset();renderQuickLinkManager();message('quickLinkMessage','Link added to the draft. Save to apply.',true);}catch(err){message('quickLinkMessage',err.message||'Enter a valid HTTPS website URL.');}});
$('saveQuickLinks').addEventListener('click',async()=>{try{const data=await api('/api/me',{method:'PATCH',body:{quickLinks:quickLinksDraft}});currentUser={...currentUser,...data.user};renderQuickLinks();renderQuickLinkManager();message('quickLinkMessage','Your shortcuts were saved.',true);toast('Quick links saved.');}catch(e){message('quickLinkMessage',e.message);}});

function toLocalInput(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))return '';const local=new Date(d.getTime()-d.getTimezoneOffset()*60000);return local.toISOString().slice(0,16);}
function localInputIso(value){const d=new Date(value);if(!Number.isFinite(d.getTime()))throw new Error('Enter a valid date and time.');return d.toISOString();}
function defaultQuestion(){return {prompt:'',type:'single_choice',options:['Option A','Option B','Option C','Option D'],correctAnswers:['Option A'],points:1,explanation:''};}
function questionEditorMarkup(q={}){const id=`q_${Math.random().toString(36).slice(2,10)}`;const type=q.type||'single_choice';const options=Array.isArray(q.options)?q.options:[];const answers=Array.isArray(q.correctAnswers)?q.correctAnswers:[];return `<article class="question-editor" data-question-editor="${id}"><div class="question-editor-heading"><b>Question</b><button class="btn danger small" type="button" data-remove-question="${id}">Remove</button></div><label>Question prompt<textarea data-q-prompt rows="2" required minlength="3" maxlength="1000" placeholder="Type the question…">${escapeHtml(q.prompt||'')}</textarea></label><div class="two-col"><label>Question type<select data-q-type><option value="single_choice" ${type==='single_choice'?'selected':''}>Single choice</option><option value="multiple_choice" ${type==='multiple_choice'?'selected':''}>Multiple choice</option><option value="true_false" ${type==='true_false'?'selected':''}>True / false</option><option value="short_answer" ${type==='short_answer'?'selected':''}>Short answer</option></select></label><label>Points<input data-q-points type="number" min="1" max="100" value="${Number(q.points||1)}" required></label></div><label data-q-options-wrap ${type==='short_answer'?'hidden':''}>Options (one per line)<textarea data-q-options rows="3" maxlength="2500" placeholder="Option A&#10;Option B">${escapeHtml((type==='true_false'?['True','False']:options).join('\n'))}</textarea></label><label>Correct answer(s)${type==='multiple_choice'?' (separate correct options with |)':type==='short_answer'?' (accepted variants separated with |)':''}<input data-q-correct required maxlength="1000" value="${escapeHtml(answers.join(' | '))}" placeholder="Enter the exact correct option or answer"></label><label>Explanation (optional)<textarea data-q-explanation rows="2" maxlength="1000" placeholder="Explain the answer after the quiz…">${escapeHtml(q.explanation||'')}</textarea></label></article>`;}
function addQuestionEditor(q=defaultQuestion()){if($('questionEditors').children.length>=100){toast('A quiz can contain at most 100 questions.');return;}$('questionEditors').insertAdjacentHTML('beforeend',questionEditorMarkup(q));const editor=$('questionEditors').lastElementChild;const type=editor.querySelector('[data-q-type]');const options=editor.querySelector('[data-q-options]');const wrap=editor.querySelector('[data-q-options-wrap]');type.addEventListener('change',()=>{const answer=editor.querySelector('[data-q-correct]');wrap.hidden=type.value==='short_answer';if(type.value==='true_false'){options.value='True\nFalse';answer.value='True';}else if(type.value==='short_answer'){options.value='';answer.value='';}else{if(options.value==='True\nFalse'||!options.value.trim())options.value='Option A\nOption B\nOption C\nOption D';answer.value='Option A';}});}
function collectQuestionEditors(){return [...$('questionEditors').querySelectorAll('[data-question-editor]')].map((el,index)=>{const type=el.querySelector('[data-q-type]').value;const options=type==='true_false'?['True','False']:type==='short_answer'?[]:el.querySelector('[data-q-options]').value.split('\n').map(x=>x.trim()).filter(Boolean);const correctAnswers=el.querySelector('[data-q-correct]').value.split('|').map(x=>x.trim()).filter(Boolean);return {prompt:el.querySelector('[data-q-prompt]').value.trim(),type,options,correctAnswers,points:Number(el.querySelector('[data-q-points]').value),explanation:el.querySelector('[data-q-explanation]').value.trim()};});}
function resetQuizEditor(){const form=$('quizForm');form.reset();form.elements.quizId.value='';form.elements.isPublished.checked=true;form.elements.maxParticipants.value='100';form.elements.durationMinutes.value='30';$('quizEditorHeading').textContent='Create a quiz';$('quizAdminMessage').textContent='';$('questionEditors').innerHTML='';addQuestionEditor();}
function fillQuizEditor(q){const f=$('quizForm');f.elements.quizId.value=q.id;f.elements.title.value=q.title;f.elements.description.value=q.description||'';f.elements.startsAt.value=toLocalInput(q.startsAt);f.elements.endsAt.value=toLocalInput(q.endsAt);f.elements.durationMinutes.value=q.durationMinutes;f.elements.maxParticipants.value=q.maxParticipants;f.elements.isPublished.checked=Boolean(q.isPublished);$('quizEditorHeading').textContent=`Edit quiz: ${q.title}`;$('questionEditors').innerHTML='';(q.questionDetails||[]).forEach(x=>addQuestionEditor({...x,correctAnswers:x.correctAnswers||[]}));if(!q.questionDetails?.length)addQuestionEditor();$('quizAdminMessage').textContent='';window.scrollTo({top:$('quizAdminPanel').getBoundingClientRect().top+window.scrollY-90,behavior:'smooth'});}
function quizCard(q){const attempt=q.attempt;let action='';if(q.state==='upcoming')action=`<button class="btn secondary small" disabled>Opens ${escapeHtml(dateFmt(q.startsAt))}</button>`;else if(q.state==='open'&&!attempt)action=q.participantCount>=q.maxParticipants?'<button class="btn secondary small" disabled>Quiz full</button>':`<button class="btn primary small" data-start-quiz="${escapeHtml(q.id)}">Start quiz</button>`;else if(attempt?.status==='in_progress')action=`<button class="btn primary small" data-start-quiz="${escapeHtml(q.id)}">Continue attempt</button>`;else if(q.state==='ended')action=`<button class="btn primary small" data-quiz-board="${escapeHtml(q.id)}">View leaderboard</button>`;else if(attempt)action='<button class="btn secondary small" disabled>Submitted · awaiting results</button>';else action='<button class="btn secondary small" disabled>Not available</button>';const prize=attempt?.prizeAwarded&&!attempt?.prizeReceived?`<p class="prize-pending">🏅 Cash prize selected: ₹${Number(attempt.prizeAmount||0).toLocaleString('en-IN')} <button class="btn primary small" data-confirm-prize="${escapeHtml(q.id)}">Confirm prize received</button></p>`:attempt?.prizeReceived?`<p class="prize-confirmed">✓ Prize receipt confirmed: ₹${Number(attempt.prizeAmount||0).toLocaleString('en-IN')}</p>`:'';return `<article class="quiz-card"><div class="quiz-card-top"><span class="challenge-meta">${q.state==='open'?'OPEN NOW':q.state==='upcoming'?'UPCOMING':'RESULTS PUBLISHED'}</span><span class="quiz-capacity">${q.participantCount}/${q.maxParticipants} participants</span></div><h4>${escapeHtml(q.title)}</h4><p>${escapeHtml(q.description||'An admin-created timed quiz.')}</p><div class="quiz-meta-grid"><span><small>QUESTIONS</small><b>${q.questionCount}</b></span><span><small>MAX SCORE</small><b>${q.totalPoints}</b></span><span><small>TIME LIMIT</small><b>${q.durationMinutes} min</b></span></div><p class="muted">${q.state==='ended'?'Closed':`Opens ${dateFmt(q.startsAt)}`} · Ends ${dateFmt(q.endsAt)}</p>${attempt&&q.state==='ended'&&attempt.score!==undefined?`<p class="quiz-own-score">Your score: <b>${attempt.score}/${q.totalPoints}</b></p>`:''}${prize}<div class="person-actions">${action}</div></article>`;}
async function loadQuizzes(){try{const d=await api('/api/quizzes');$('quizList').innerHTML=d.quizzes.map(quizCard).join('')||'<div class="empty-state">No quizzes have been published yet. Check back soon.</div>';if(currentUser?.isAdmin){$('quizAdminPanel').hidden=false;await loadAdminQuizzes();}}catch(e){$('quizList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function loadAdminQuizzes(){if(!currentUser?.isAdmin)return;try{const d=await api('/api/admin/quizzes');$('adminQuizList').innerHTML=d.quizzes.map(q=>`<article class="admin-quiz-row"><div class="person-main"><b>${escapeHtml(q.title)}</b><small>${escapeHtml(q.state)} · ${q.attemptCount} attempt(s) · ${q.participantCount}/${q.maxParticipants} seats · ${q.questionCount} questions</small><small>${dateFmt(q.startsAt)} – ${dateFmt(q.endsAt)}</small></div><div class="person-actions"><button class="btn secondary small" data-edit-quiz="${escapeHtml(q.id)}" ${q.attemptCount?'disabled':''}>Edit</button><button class="btn secondary small" data-toggle-quiz="${escapeHtml(q.id)}" data-published="${q.isPublished?'true':'false'}" ${(q.attemptCount>0&&q.isPublished)?'disabled title="Cannot hide a quiz after attempts; public results must remain visible"':''}>${q.isPublished?'Published':'Publish'}</button><button class="btn secondary small" data-admin-quiz-board="${escapeHtml(q.id)}" ${q.state!=='ended'?'disabled':''}>Leaderboard</button><button class="btn danger small" data-delete-quiz="${escapeHtml(q.id)}">Delete</button></div></article>`).join('')||'<div class="empty-state">No quizzes created yet.</div>';window._adminQuizCache=d.quizzes;}catch(e){$('adminQuizList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('addQuestionButton').addEventListener('click',()=>addQuestionEditor());
$('resetQuizForm').addEventListener('click',resetQuizEditor);
$('refreshQuizzes').addEventListener('click',loadQuizzes);
$('refreshAdminQuizzes').addEventListener('click',loadAdminQuizzes);
$('quizForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const id=String(f.get('quizId')||'');try{const body={title:f.get('title'),description:f.get('description'),startsAt:localInputIso(f.get('startsAt')),endsAt:localInputIso(f.get('endsAt')),durationMinutes:Number(f.get('durationMinutes')),maxParticipants:Number(f.get('maxParticipants')),isPublished:f.get('isPublished')==='on',questions:collectQuestionEditors()};const path=id?`/api/admin/quizzes/${id}`:'/api/admin/quizzes';const result=await api(path,{method:id?'PATCH':'POST',body});message('quizAdminMessage',result.message||'Quiz saved.',true);resetQuizEditor();await Promise.all([loadQuizzes(),loadAdminQuizzes()]);}catch(err){message('quizAdminMessage',err.message);}});

function runnerAnswerFor(question, answers){return answers.find(a=>String(a.questionId)===String(question.id))?.response||[];}
function renderQuizRunner(data){activeQuiz={id:data.quiz.id,deadlineAt:data.attempt.deadlineAt,questions:data.quiz.questions,startedAt:data.attempt.startedAt};$('quizRunnerTitle').textContent=data.quiz.title;$('quizRunnerDescription').textContent=`${data.quiz.questions.length} questions · Each question shows its points. Answers are autosaved; leaving this dialog does not pause the clock.`;const answers=data.attempt.answers||[];$('quizRunnerQuestions').innerHTML=data.quiz.questions.map((q,i)=>{const val=runnerAnswerFor(q,answers);let controls='';if(q.type==='short_answer')controls=`<input type="text" data-answer-question="${escapeHtml(q.id)}" data-answer-kind="text" maxlength="1000" value="${escapeHtml(val[0]||'')}" placeholder="Type your answer…">`;else controls=(q.options||[]).map(opt=>{const type=q.type==='multiple_choice'?'checkbox':'radio';const checked=val.some(v=>v.toLocaleLowerCase()===opt.toLocaleLowerCase());return `<label class="quiz-option"><input type="${type}" name="q_${escapeHtml(q.id)}" value="${escapeHtml(opt)}" data-answer-question="${escapeHtml(q.id)}" ${checked?'checked':''}><span>${escapeHtml(opt)}</span></label>`;}).join('');return `<article class="quiz-question"><div class="quiz-question-heading"><span>QUESTION ${i+1}</span><b>${q.points} point${q.points===1?'':'s'}</b></div><h4>${escapeHtml(q.prompt)}</h4><div class="quiz-answer-options">${controls}</div></article>`;}).join('');$('quizRunnerStatus').textContent='';$('quizDialog').showModal();startQuizClock();}
function collectRunnerAnswers(){return activeQuiz.questions.map(q=>{const id=String(q.id);if(q.type==='short_answer'){const el=$('quizRunnerQuestions').querySelector(`[data-answer-question="${CSS.escape(id)}"][data-answer-kind="text"]`);return {questionId:id,response:el?.value.trim()?[el.value.trim()]:[]};}const els=[...$('quizRunnerQuestions').querySelectorAll(`[data-answer-question="${CSS.escape(id)}"]:checked`)];return {questionId:id,response:els.map(el=>el.value)};});}
function scheduleQuizAutosave(){if(!activeQuiz||Date.now()>=new Date(activeQuiz.deadlineAt).getTime())return;clearTimeout(quizAutosaveTimer);quizAutosaveTimer=setTimeout(async()=>{if(!activeQuiz||quizAutosaveBusy)return;quizAutosaveBusy=true;try{await api(`/api/quizzes/${activeQuiz.id}/attempt`,{method:'PUT',body:{answers:collectRunnerAnswers()}});message('quizRunnerStatus','Answers saved.',true);}catch(e){message('quizRunnerStatus',e.message);}finally{quizAutosaveBusy=false;}},350);}
function startQuizClock(){clearInterval(quizTimerInterval);const update=()=>{if(!activeQuiz)return;const seconds=Math.max(0,Math.ceil((new Date(activeQuiz.deadlineAt).getTime()-Date.now())/1000));const m=Math.floor(seconds/60),s=seconds%60;$('quizTimer').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('quizTimer').classList.toggle('urgent',seconds<=60);if(seconds<=0){clearInterval(quizTimerInterval);submitQuizAttempt(true).catch(e=>toast(e.message));}};update();quizTimerInterval=setInterval(update,1000);}
async function startQuiz(id){try{const d=await api(`/api/quizzes/${id}/start`,{method:'POST',body:{}});if(d.attempt?.status&&d.attempt.status!=='in_progress'){toast('Your quiz was already submitted.');await loadQuizzes();return;}renderQuizRunner(d);}catch(e){toast(e.message);await loadQuizzes();}}
async function submitQuizAttempt(auto=false){if(!activeQuiz)return;const quizId=activeQuiz.id;clearInterval(quizTimerInterval);clearTimeout(quizAutosaveTimer);$('submitQuizButton').disabled=true;message('quizRunnerStatus',auto?'Time ended. Submitting saved answers…':'Submitting quiz…');try{const body=auto?{}:{answers:collectRunnerAnswers()};const d=await api(`/api/quizzes/${quizId}/submit`,{method:'POST',body});$('quizDialog').close();activeQuiz=null;toast(d.message||'Quiz submitted.');await loadQuizzes();if(d.resultsPublished)await showQuizLeaderboard(quizId);}catch(e){message('quizRunnerStatus',e.message);if(auto){$('quizDialog').close();activeQuiz=null;await loadQuizzes();toast(e.message);}}finally{$('submitQuizButton').disabled=false;}}
$('quizRunnerForm').addEventListener('change',scheduleQuizAutosave);
$('quizRunnerForm').addEventListener('input',scheduleQuizAutosave);
$('quizRunnerForm').addEventListener('submit',e=>{e.preventDefault();submitQuizAttempt(false);});
$('closeQuizDialog').addEventListener('click',()=>{clearInterval(quizTimerInterval);$('quizDialog').close();});
$('closeQuizLeaderboard').addEventListener('click',()=>{$('quizLeaderboardPanel').hidden=true;});
async function showQuizLeaderboard(quizId){try{const d=await api(`/api/quizzes/${quizId}/leaderboard`);$('quizLeaderboardPanel').hidden=false;$('quizLeaderboardTitle').textContent=`${d.quiz.title} leaderboard`;$('quizLeaderboardRules').textContent=d.rules;$('quizLeaderboardList').innerHTML=d.leaderboard.map(row=>{const prize=row.prize?`<span class="prize-confirmed">🏆 Cash prize received: ₹${Number(row.prize.amount||0).toLocaleString('en-IN')}${row.prize.note?` · ${escapeHtml(row.prize.note)}`:''}</span>`:'';const adminActions=currentUser?.isAdmin?`<button class="btn secondary small" data-admin-profile="${escapeHtml(quizId)}" data-attempt-profile="${escapeHtml(row.attemptId)}">Full profile</button><button class="btn ${row.prizeAwarded?'secondary':'primary'} small" data-award-prize="${escapeHtml(quizId)}" data-prize-attempt="${escapeHtml(row.attemptId)}" data-prize-awarded="${row.prizeAwarded?'true':'false'}" data-prize-amount="${Number(row.prizeAmount||0)}">${row.prizeAwarded?'Edit prize':'Mark cash prize'}</button>`:'';return `<div class="quiz-rank-row"><span class="rank-num">#${row.rank}</span>${avatar(row.user)}<div class="person-main"><b>${escapeHtml(row.user.displayName)}</b><small>@${escapeHtml(row.user.username)} · ${row.score}/${row.totalPoints} points · ${Math.floor(row.elapsedSeconds/60)}m ${row.elapsedSeconds%60}s</small>${prize}</div>${adminActions}</div>`;}).join('')||'<div class="empty-state">No completed attempts are available for this quiz.</div>';window._activeLeaderboardQuiz=quizId;}catch(e){toast(e.message);}}
async function showAdminParticipantProfile(quizId,attemptId){const dialog=$('publicProfileDialog');const content=$('publicProfileContent');content.innerHTML='<div class="empty-state">Loading private participant profile…</div>';dialog.showModal();try{const d=await api(`/api/admin/quizzes/${quizId}/attempts/${attemptId}/profile`);const u=d.profile,a=d.attempt;content.innerHTML=`<div class="profile-cover">${avatar(u)}<div><h3>${escapeHtml(u.displayName)}</h3><p>@${escapeHtml(u.username)} · ${escapeHtml(u.role)}</p></div></div><div class="admin-private-data"><h4>Contact details (admin only)</h4><p><b>Email:</b> ${u.email?`<a href="mailto:${escapeHtml(u.email)}">${escapeHtml(u.email)}</a>`:'Not available'}</p><p><b>Phone:</b> ${u.phoneNumber?`<a href="tel:${escapeHtml(u.phoneNumber)}">${escapeHtml(u.phoneNumber)}</a>`:'Not provided'}</p><p><b>Email verified:</b> ${u.emailVerified?'Yes':'No'} · <b>Suspended:</b> ${u.suspended?'Yes':'No'}</p><p><b>Joined:</b> ${dateFmt(u.createdAt)} · <b>Last active:</b> ${dateFmt(u.lastActiveAt)}</p><h4>Profile data</h4><p><b>Bio:</b> ${escapeHtml(u.bio||'—')}</p><p><b>Interests:</b> ${escapeHtml((u.interests||[]).join(', ')||'—')}</p><p><b>Learning goals:</b> ${escapeHtml((u.learningGoals||[]).join(', ')||'—')}</p><p><b>Achievements:</b> ${escapeHtml((u.achievements||[]).join(', ')||'—')} · <b>Friends:</b> ${Number(u.friendsCount||0)}</p><p><b>Privacy:</b> ${escapeHtml(u.privacy?.profileVisibility||'public')} · Leaderboard visibility: ${u.privacy?.showOnLeaderboard?'On':'Off'}</p><p><b>Quick links:</b> ${(u.quickLinks||[]).map(l=>`<a href="${escapeHtml(l.url)}" target="_blank" rel="noopener noreferrer">${escapeHtml(l.label)}</a>`).join(' · ')||'—'}</p><h4>Quiz attempt</h4><p><b>Result:</b> ${a.score}/${a.totalPoints} · <b>Time:</b> ${Math.floor(a.elapsedSeconds/60)}m ${a.elapsedSeconds%60}s · <b>Status:</b> ${escapeHtml(a.status)}</p><p><b>Prize:</b> ${a.prizeAwarded?`Selected ₹${Number(a.prizeAmount||0).toLocaleString('en-IN')}${a.prizeReceived?' · receipt confirmed by user':''}`:'Not selected'}</p><div class="person-actions"><a class="btn secondary small" href="mailto:${escapeHtml(u.email||'')}?subject=${encodeURIComponent('Study Lock quiz result')}">Contact by email</a>${u.phoneNumber?`<a class="btn secondary small" href="tel:${escapeHtml(u.phoneNumber)}">Call / message</a>`:''}</div></div>`;}catch(e){content.innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
async function changePrize(quizId,attemptId,currentAwarded,currentAmount){let awarded=true;let amount=Number(currentAmount||0);if(currentAwarded){const action=prompt('This profile is already marked for a cash prize. Enter a new amount to update it, or type REMOVE to revoke it:',String(amount));if(action===null)return;if(action.trim().toUpperCase()==='REMOVE')awarded=false;else{amount=Number(action);if(!Number.isFinite(amount)||amount<=0){toast('Enter a valid positive prize amount.');return;}}}else{const value=prompt('Cash prize amount in INR (₹):','500');if(value===null)return;amount=Number(value);if(!Number.isFinite(amount)||amount<=0){toast('Enter a valid positive prize amount.');return;}}let note='';if(awarded){note=prompt('Optional public note for the winner (visible only after they confirm receipt):','')||'';}await api(`/api/admin/quizzes/${quizId}/attempts/${attemptId}/prize`,{method:'PATCH',body:{awarded,amount,note}});toast(awarded?'Cash prize selection saved. The winner can confirm receipt.':'Cash prize selection revoked.');await showQuizLeaderboard(quizId);await loadQuizzes();await loadAdminQuizzes();}
async function confirmPrize(quizId){if(!confirm('Confirm that you actually received this cash prize? Once confirmed, the prize amount will be shown to everyone on the leaderboard.'))return;try{const d=await api(`/api/quizzes/${quizId}/prize/confirm`,{method:'POST',body:{}});toast(d.message);await loadQuizzes();await showQuizLeaderboard(quizId);}catch(e){toast(e.message);}}

async function loadAdminChallenges(){if(!currentUser?.isAdmin)return;try{const d=await api('/api/admin/challenges');$('adminChallengeList').innerHTML=d.challenges.map(c=>`<article class="admin-challenge-row"><div class="person-main"><b>${escapeHtml(c.title)}</b><small>${c.participantCount} participants · ${escapeHtml(c.type)} · ${escapeHtml(c.visibility)}</small><small>By @${escapeHtml(c.creator?.username||'deleted-user')} · Ends ${dateFmt(c.endsAt)}</small></div><div class="person-actions"><button class="btn secondary small" data-edit-admin-challenge="${escapeHtml(c.id)}">Edit</button><button class="btn danger small" data-delete-admin-challenge="${escapeHtml(c.id)}">Delete</button></div></article>`).join('')||'<div class="empty-state">No challenges to manage.</div>';window._adminChallengeCache=d.challenges;}catch(e){$('adminChallengeList').innerHTML=`<div class="empty-state">${escapeHtml(e.message)}</div>`;}}
$('refreshAdminChallenges').addEventListener('click',loadAdminChallenges);
async function editAdminChallenge(id){const c=(window._adminChallengeCache||[]).find(x=>x.id===id);if(!c)return;const f=$('challengeForm');f.elements.challengeId.value=c.id;f.elements.title.value=c.title;f.elements.description.value=c.description||'';f.elements.type.value=c.type;f.elements.goal.value=c.goal;f.elements.endsAt.value=toLocalInput(c.endsAt);f.elements.visibility.value=c.visibility;$('challengeFormHeading').textContent='Edit challenge';$('challengeMessage').textContent='Editing an existing challenge.';window.scrollTo({top:f.getBoundingClientRect().top+window.scrollY-100,behavior:'smooth'});}

// Authentication
for(const b of document.querySelectorAll('[data-auth-tab]'))b.addEventListener('click',()=>setAuthTab(b.dataset.authTab));
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();message('loginMessage','Signing in…');const f=new FormData(e.currentTarget);try{await afterAuth(await api('/api/auth/login',{method:'POST',body:{emailOrUsername:f.get('emailOrUsername'),password:f.get('password')}}));message('loginMessage','',true);}catch(err){message('loginMessage',err.message);}});
$('registerForm').addEventListener('submit',async e=>{e.preventDefault();message('registerMessage','Creating account…');const f=new FormData(e.currentTarget);try{const result=await api('/api/auth/register',{method:'POST',body:{displayName:f.get('displayName'),username:f.get('username'),email:f.get('email'),phoneNumber:f.get('phoneNumber'),password:f.get('password'),joinLeaderboard:f.get('joinLeaderboard')==='on',acceptTerms:f.get('acceptTerms')==='on'}});if(result.verificationRequired){message('registerMessage',result.message,true);return;}await afterAuth(result);message('registerMessage','',true);}catch(err){message('registerMessage',err.message);}});
$('signOutButton').addEventListener('click',async()=>{try{if(token)await api('/api/auth/logout',{method:'POST'});}catch{}token='';localStorage.removeItem(TOKEN_KEY);selectedConversation=null;showAuth();toast('Signed out.');});
$('forgotPasswordButton').addEventListener('click',async()=>{const email=prompt('Enter the email address for your account:');if(!email)return;try{const d=await api('/api/auth/forgot-password',{method:'POST',body:{email}});message('loginMessage',d.message,true);}catch(e){message('loginMessage',e.message);}});
$('resendVerificationButton').addEventListener('click',async()=>{const email=prompt('Enter the email address you used to register:');if(!email)return;try{const d=await api('/api/auth/resend-verification',{method:'POST',body:{email}});message('loginMessage',d.message,true);}catch(e){message('loginMessage',e.message);}});
$('resetPasswordForm').addEventListener('submit',async e=>{e.preventDefault();const tokenParam=new URLSearchParams(location.search).get('resetToken');const password=new FormData(e.currentTarget).get('password');try{const d=await api('/api/auth/reset-password',{method:'POST',body:{token:tokenParam,password}});message('resetMessage',d.message,true);history.replaceState({},'',location.pathname);$('resetPasswordForm').hidden=true;$('loginForm').hidden=false;}catch(err){message('resetMessage',err.message);}});
$('cancelResetButton').addEventListener('click',()=>{history.replaceState({},'',location.pathname);$('resetPasswordForm').hidden=true;$('loginForm').hidden=false;});
$('refreshReports')?.addEventListener('click',()=>loadAdminReports().catch(e=>toast(e.message)));$('refreshReportsAdmin')?.addEventListener('click',()=>loadAdminReports().catch(e=>toast(e.message)));
// Main navigation
for(const b of document.querySelectorAll('[data-view]'))b.addEventListener('click',()=>showView(b.dataset.view));
for(const b of document.querySelectorAll('[data-goto]'))b.addEventListener('click',()=>showView(b.dataset.goto));
$('leaderboardPeriod').addEventListener('change',loadLeaderboard);$('refreshLeaderboard').addEventListener('click',loadLeaderboard);$('refreshStats').addEventListener('click',loadOverview);$('discoverForm').addEventListener('submit',e=>{e.preventDefault();loadDiscover($('discoverQuery').value.trim());});$('refreshFriends').addEventListener('click',loadFriends);$('refreshConversations').addEventListener('click',loadConversations);$('refreshChallenges').addEventListener('click',loadChallenges);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.editLink!==undefined){const i=Number(b.dataset.editLink);const link=quickLinksDraft[i];if(link){const label=prompt('Website name:',link.label);if(label===null)return;const url=prompt('HTTPS website URL:',link.url);if(url===null)return;const icon=prompt('Icon (emoji):',link.icon||'🔗');if(icon===null)return;try{const parsed=new URL(url.trim());if(parsed.protocol!=='https:'||!parsed.hostname||parsed.username||parsed.password)throw new Error('Use a valid HTTPS URL.');if(!label.trim())throw new Error('Website name is required.');quickLinksDraft[i]={label:label.trim(),url:parsed.toString(),icon:icon.trim()||'🔗'};renderQuickLinkManager();message('quickLinkMessage','Changes are in the draft. Save to apply.',true);}catch(err){toast(err.message);}}}
 else if(b.dataset.deleteLink!==undefined){const i=Number(b.dataset.deleteLink);quickLinksDraft.splice(i,1);renderQuickLinkManager();message('quickLinkMessage','Link removed from the draft. Save to apply.',true);}
 else if(b.dataset.removeQuestion){document.querySelector(`[data-question-editor="${CSS.escape(b.dataset.removeQuestion)}"]`)?.remove();}
 else if(b.dataset.startQuiz){await startQuiz(b.dataset.startQuiz);}
 else if(b.dataset.quizBoard){await showQuizLeaderboard(b.dataset.quizBoard);}
 else if(b.dataset.adminQuizBoard){await showQuizLeaderboard(b.dataset.adminQuizBoard);}
 else if(b.dataset.editQuiz){const q=(window._adminQuizCache||[]).find(x=>x.id===b.dataset.editQuiz);if(q){showView('quizzes');fillQuizEditor(q);}}
 else if(b.dataset.deleteQuiz){if(!confirm('Delete this quiz and all participant attempts? This cannot be undone.'))return;await api(`/api/admin/quizzes/${b.dataset.deleteQuiz}`,{method:'DELETE'});toast('Quiz deleted.');resetQuizEditor();await Promise.all([loadQuizzes(),loadAdminQuizzes()]);}
 else if(b.dataset.toggleQuiz){const publish=b.dataset.published!=='true';await api(`/api/admin/quizzes/${b.dataset.toggleQuiz}`,{method:'PATCH',body:{isPublished:publish}});toast(publish?'Quiz published.':'Quiz unpublished.');await Promise.all([loadQuizzes(),loadAdminQuizzes()]);}
 else if(b.dataset.adminProfile){await showAdminParticipantProfile(b.dataset.adminProfile,b.dataset.attemptProfile);}
 else if(b.dataset.awardPrize){await changePrize(b.dataset.awardPrize,b.dataset.prizeAttempt,b.dataset.prizeAwarded==='true',Number(b.dataset.prizeAmount||0));}
 else if(b.dataset.confirmPrize){await confirmPrize(b.dataset.confirmPrize);}
 else if(b.dataset.editAdminChallenge){await editAdminChallenge(b.dataset.editAdminChallenge);}
 else if(b.dataset.deleteAdminChallenge){if(!confirm('Delete this challenge for all participants?'))return;await api(`/api/admin/challenges/${b.dataset.deleteAdminChallenge}`,{method:'DELETE'});toast('Challenge deleted.');await loadChallenges();}
 else if(b.dataset.viewProfile){await showPublicProfile(b.dataset.viewProfile);}
 else if(b.dataset.reportStatus){if(b.dataset.reportStatus==='actioned'){if(b.dataset.targetType==='user'){if(!confirm('Suspend this reported account?'))return;const reason=prompt('Suspension reason:','Community guideline violation');if(reason===null)return;await api(`/api/admin/users/${b.dataset.targetId}/suspension`,{method:'PATCH',body:{suspended:true,reason:reason||'Community guideline violation'}});}else if(b.dataset.targetType==='challenge'){if(!confirm('Delete the reported challenge?'))return;await api(`/api/admin/challenges/${b.dataset.targetId}`,{method:'DELETE'});}else if(b.dataset.targetType==='message'){if(!confirm('Delete the reported message?'))return;await api(`/api/admin/messages/${b.dataset.targetId}`,{method:'DELETE'});}}await api(`/api/admin/reports/${b.dataset.reportId}`,{method:'PATCH',body:{status:b.dataset.reportStatus}});toast('Report status updated.');await loadAdminReports();}
 else if(b.dataset.addFriend) await requestFriend(b.dataset.addFriend);
 else if(b.dataset.acceptRequest) await acceptRequest(b.dataset.acceptRequest);
 else if(b.dataset.declineRequest) await declineRequest(b.dataset.declineRequest);
 else if(b.dataset.removeFriend) await removeFriend(b.dataset.removeFriend);
 else if(b.dataset.blockUser) await blockUser(b.dataset.blockUser);
 else if(b.dataset.reportUser) await reportTarget('user',b.dataset.reportUser);
 else if(b.dataset.reportMessage) await reportTarget('message',b.dataset.reportMessage);
 else if(b.dataset.reportChallenge) await reportTarget('challenge',b.dataset.reportChallenge);
 else if(b.dataset.joinChallenge) await joinChallenge(b.dataset.joinChallenge);
 else if(b.dataset.refreshChallengeProgress) await updateChallenge(b.dataset.refreshChallengeProgress);
 else if(b.dataset.messageUser) {selectedConversation={userId:b.dataset.messageUser,username:b.dataset.username};showView('messages');await openConversation(selectedConversation.userId,selectedConversation.username);}
 else if(b.dataset.openConversation) await openConversation(b.dataset.openConversation,b.dataset.username);
 }catch(err){toast(err.message);}});
$('sendMessageForm').addEventListener('submit',async e=>{e.preventDefault();if(!selectedConversation)return;const body=$('messageBody').value.trim();if(!body)return;const btn=e.submitter;btn.disabled=true;try{await api(`/api/conversations/${selectedConversation.userId}/messages`,{method:'POST',body:{body}});$('messageBody').value='';await loadMessages();await loadConversations();}catch(err){message('chatStatus',err.message);}finally{btn.disabled=false;}});
$('blockChatUser').addEventListener('click',()=>selectedConversation&&blockUser(selectedConversation.userId));
$('profileForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const data=await api('/api/me',{method:'PATCH',body:{displayName:f.get('displayName'),phoneNumber:f.get('phoneNumber'),bio:f.get('bio'),avatarUrl:f.get('avatarUrl'),interests:String(f.get('interests')||'').split(',').map(x=>x.trim()).filter(Boolean),learningGoals:String(f.get('learningGoals')||'').split(',').map(x=>x.trim()).filter(Boolean)}});currentUser={...currentUser,...data.user,quickLinks:currentUser.quickLinks||[]};message('profileMessage','Profile saved.',true);$('welcomeName').textContent=currentUser.displayName;}catch(err){message('profileMessage',err.message);}});
$('privacyForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/api/me',{method:'PATCH',body:{privacy:{profileVisibility:f.get('profileVisibility'),showOnLeaderboard:f.get('showOnLeaderboard')==='on',showStudyStats:f.get('showStudyStats')==='on',allowFriendRequests:f.get('allowFriendRequests')==='on',allowMessages:f.get('allowMessages')}}});message('privacyMessage','Privacy settings saved.',true);await loadOverview();}catch(err){message('privacyMessage',err.message);}});
$('challengeForm').addEventListener('submit',async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const end=new Date(f.get('endsAt'));const id=String(f.get('challengeId')||'');try{const body={title:f.get('title'),description:f.get('description'),type:f.get('type'),goal:Number(f.get('goal')),endsAt:end.toISOString(),visibility:f.get('visibility')};if(id){if(!currentUser?.isAdmin)throw new Error('Only admins can edit community challenges.');await api(`/api/admin/challenges/${id}`,{method:'PATCH',body});message('challengeMessage','Challenge updated.',true);}else{await api('/api/challenges',{method:'POST',body});message('challengeMessage','Challenge created.',true);}e.currentTarget.reset();e.currentTarget.elements.challengeId.value='';$('challengeFormHeading').textContent='Create a challenge';await loadChallenges();}catch(err){message('challengeMessage',err.message);}});
$('downloadData').addEventListener('click',async()=>{try{await exportData();toast('Your community data export is ready.');}catch(e){toast(e.message);}});$('deleteAccount').addEventListener('click',async()=>{try{await deleteAccount();}catch(e){toast(e.message);}});
async function init(){try{const r=await fetch('/health');if(r.ok){const d=await r.json();$('apiStatus').textContent=d.database==='connected'?'API and database online':`API online · database ${d.database}`;}}catch{$('apiStatus').textContent='API status unavailable';}const params=new URLSearchParams(location.search);if(params.get('verified')==='1'){history.replaceState({},'',location.pathname);toast('Email verified. You can now sign in.');}if(params.has('resetToken')){$('loginForm').hidden=true;$('registerForm').hidden=true;$('resetPasswordForm').hidden=false;}if(params.has('resetToken')){token='';localStorage.removeItem(TOKEN_KEY);showAuth();$('loginForm').hidden=true;$('registerForm').hidden=true;$('resetPasswordForm').hidden=false;return;}if(token){try{await loadMe();}catch(e){token='';localStorage.removeItem(TOKEN_KEY);showAuth();}}else showAuth();}
init();
